//! Reproduces the textual output of C++ `std::ostream` for floating point
//! values: default field precision of 6 significant digits, `%g` style
//! selection between fixed and scientific notation, trailing zeros removed.

/// `std::ios_base` starts out with a precision of 6.
const DEFAULT_PRECISION: usize = 6;

/// Formats a `float` the way `std::cout << value` does (the value is widened
/// to `double` by the stream insertion, exactly like in C++).
pub fn ostream_float(value: f32) -> String {
    ostream_double(value as f64)
}

/// Formats a `double` the way `std::cout << value` does.
pub fn ostream_double(value: f64) -> String {
    if value.is_nan() {
        // glibc prints the sign bit of a quiet NaN, hence "-nan".
        return if value.is_sign_negative() { "-nan" } else { "nan" }.to_string();
    }
    if value.is_infinite() {
        return if value.is_sign_negative() { "-inf" } else { "inf" }.to_string();
    }
    format_g(value, DEFAULT_PRECISION)
}

/// `printf("%g")` with the given significant-digit precision.
fn format_g(value: f64, precision: usize) -> String {
    let significant = if precision == 0 { 1 } else { precision };

    // Round to `significant` digits first: the decimal exponent of that
    // rounded value is what decides between the two notations.
    let scientific = format!("{:.*e}", significant - 1, value);
    let split = scientific.find('e').expect("scientific notation has an exponent");
    let exponent: i32 = scientific[split + 1..].parse().expect("integral exponent");

    if exponent < -4 || exponent >= significant as i32 {
        let mantissa = trim_trailing_zeros(&scientific[..split]);
        let sign = if exponent < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mantissa, sign, exponent.abs())
    } else {
        let decimals = (significant as i32 - 1 - exponent) as usize;
        trim_trailing_zeros(&format!("{:.*}", decimals, value)).to_string()
    }
}

/// Drops the trailing zeros of a fractional part, and the now dangling
/// decimal point, as `%g` does without the `#` flag.
fn trim_trailing_zeros(text: &str) -> String {
    if !text.contains('.') {
        return text.to_string();
    }
    let trimmed = text.trim_end_matches('0');
    trimmed.strip_suffix('.').unwrap_or(trimmed).to_string()
}

