mod format;
use format::ostream_float;

// model: 0 = rgb f64 / hsl f64, 1 = rgb f64 / hsl f32,
//        2 = rgb f32 / hsl f64, 3 = rgb f32 / hsl f32
fn yuv_to_rgb(model: u32, y: f32, u: f32, v: f32) -> (f32, f32, f32) {
    if model < 2 {
        let (y, u, v) = (y as f64, u as f64, v as f64);
        (
            (y + 1.140 * v) as f32,
            (y - 0.395 * u - 0.581 * v) as f32,
            (y + 2.032 * u) as f32,
        )
    } else {
        (
            y + 1.140f32 * v,
            y - 0.395f32 * u - 0.581f32 * v,
            y + 2.032f32 * u,
        )
    }
}

fn rgb_to_hsl(model: u32, r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let hsl_f64 = model == 0 || model == 2;
    let cmin = fmin(r, fmin(g, b));
    let cmax = fmax(r, fmax(g, b));
    if hsl_f64 {
        let (r, g, b) = (r as f64, g as f64, b as f64);
        let (cminf, cmaxf) = (cmin as f64, cmax as f64);
        let delta = cmaxf - cminf;
        let l = ((cmaxf + cminf) / 2.0) as f32;
        if cmax == cmin {
            return (0.0, 0.0, l);
        }
        let s = if (l as f64) < 0.5 {
            delta / (cmaxf + cminf)
        } else {
            delta / (2.0 - cmaxf - cminf)
        } as f32;
        let mut h = if cmaxf == r {
            (g - b) / delta + if g < b { 6.0 } else { 0.0 }
        } else if cmaxf == g {
            (b - r) / delta + 2.0
        } else {
            (r - g) / delta + 4.0
        } as f32;
        h = (h as f64 * 60.0) as f32;
        (h, s, l)
    } else {
        let delta = cmax - cmin;
        let l = (cmax + cmin) / 2.0f32;
        if cmax == cmin {
            return (0.0, 0.0, l);
        }
        let s = if l < 0.5 {
            delta / (cmax + cmin)
        } else {
            delta / (2.0f32 - cmax - cmin)
        };
        let mut h = if cmax == r {
            (g - b) / delta + if g < b { 6.0f32 } else { 0.0 }
        } else if cmax == g {
            (b - r) / delta + 2.0f32
        } else {
            (r - g) / delta + 4.0f32
        };
        h *= 60.0f32;
        (h, s, l)
    }
}

// std::min / std::max semantics: (b < a) ? b : a  /  (a < b) ? b : a
fn fmin(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}
fn fmax(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let model: u32 = args[1].parse().unwrap();
    let y: f32 = args[2].parse().unwrap();
    let u: f32 = args[3].parse().unwrap();
    let v: f32 = args[4].parse().unwrap();
    let (r, g, b) = yuv_to_rgb(model, y, u, v);
    let (h, s, l) = rgb_to_hsl(model, r, g, b);
    println!(
        "{} {} {} {} {} {}",
        ostream_float(r),
        ostream_float(g),
        ostream_float(b),
        ostream_float(h),
        ostream_float(s),
        ostream_float(l)
    );
}

